script.text:
			/* <flatten type="Javascript"> */
function load$Grid(g) {
	g._$k = [];
	g._$i = g._getColumnOrder('stt_rec');
	g._$t = g._getColumnOrder('tag');
	g.add_onResponseComplete(on$GridAllocation$ResponseComplete);
	g.add_commandEvent(on$GridAllocation$ExecuteCommand);
	g.add_onRender(on$Grid$dd$Render);
}
function scatter$Grid(g) {fill$Grid(g, true);}
function dispose$Grid(g) {
	try {g.remove_commandEvent(on$GridAllocation$ExecuteCommand);} catch (ex) {}
	try {g.remove_onResponseComplete(on$GridAllocation$ResponseComplete);} catch (ex) {}
	try {g.remove_onRender(on$Grid$dd$Render);} catch (ex) {}
}
function on$GridAllocation$ExecuteCommand(sender, e) {
	var action = e.type.Action, g = sender, id = g.get_id(), s = String.format('$find(\'{0}\')._focusWhenTabChanged();', id);
	switch (action) {
		case 'Calc':
		case 'Allocate':
			if (isCheck$Grid(g)) request$Allocation(id, action);
			break;
		case 'Truncate':
			if (isCheck$Grid(g)) {
				var e = (g._language == 'v' ? 'Hệ thống sẽ <span class="Highlight">xóa phân bổ cho các bản ghi đang được chọn</span>, bạn có chắc chắn xóa không?' : 'The selected <span class="Highlight">allocation transactions</span> will be deleted, are you sure you want to proceed?');
				$message.show(e, 0, String.format('request$Allocation(\'{0}\', \'{1}\');', id, action), s);
			}
			break;
		case 'BeforeFormLoad':
			e.type.Value.set_vars([{Name: 'p1', Type: 'Decimal', Value: g._p1}, {Name: 'p2', Type: 'Decimal', Value: g._p2}, {Name: 'y', Type: 'Decimal', Value: g._y}, {Name: 'u', Type: 'String', Value: g._u}]);
			break;
		default:
			break;
	}
}
function request$Allocation(id, c) {
	var g = $find(id);
	if (g._rowCount == 0) return;
	var r = (g._activeCell ? g._activeRow : 1), s = ',' + g._$k.join(',') + ',', o = g._getItemValue(r, g._$t);
	o.row = r;
	g.request(o, c, c, [['p1', 'Decimal', g._p1], ['p2', 'Decimal', g._p2], ['y', 'Decimal', g._y], ['u', 'String', g._u], ['s', 'Infinite', s]]);
}
function on$GridAllocation$ResponseComplete(sender, e) {
	var g = e.object, context = e.type.Context, result = e.type.Result, o = e.type.Object;
	switch (context) {
		case 'Calc':
		case 'Allocate':
		case 'Truncate':
			if (result[0].Value != '') $message.show(result[1].Value, String.format('$find(\'{0}\')._focusWhenTabChanged();', g.get_id()));
			else {
				var msg = (g._language == 'v' ? 'Chương trình đã thực hiện xong.' : 'The process completed successfully.');
				$message.show(msg, String.format('$find(\'{0}\')._focusWhenTabChanged();', g.get_id()));
				g._$k = [];
				//fill$Grid(g);
				g.goToPage(-1);
			}
			break;
		case 'GetOtherData':
			var cIndex = [g._getColumnOrder('hs9tien')];
			for (var r = 1; r <= g._rowCount; r++) {
				for (var ci = 0; ci < cIndex.length; ci++) g._setItemValue(r, cIndex[ci], result[r - 1][ci + 1]);
			}
			break;
		default:
			break;
	}
}
function on$Grid$dd$Render(sender, eventArgs) {
	if (sender._rowCount == 0) return;
	var x = setInterval(function() { 
		if(!sender._isBusy) { 
			clearInterval(x); 

			var g = sender, lstt_rec = '';
			var ciStt_rec = g._getColumnOrder('stt_rec');
			for (var r = 1; r <= g._rowCount; r++) {
				lstt_rec += String.fromCharCode(252) + r.toString() + String.fromCharCode(253) + g._getItemValue(r, ciStt_rec);
			}

			var o = g._getItem(1, 1);
			o.row = 1;
			g.request(o, 'GetOtherData', 'GetOtherData', [['lstt_rec', 'Infinite', lstt_rec], ['p1', 'Decimal', g._p1], ['p2', 'Decimal', g._p2], ['y', 'Decimal', g._y]], [], null);
		}
	}, 50)
}
/* </flatten> */
			&ScriptTag;

css.text:

div.Edit{background-image:url(../images/Shift.png);background-repeat:no-repeat;background-position:0 0;}
div.TextEdit{background-image:url(../images/TextAsterisk.png),url(../images/Line.png);background-repeat:no-repeat,repeat-x;background-position:0 0;}
div.Calc{background-image:url(../images/calculate.png);background-repeat:no-repeat;background-position:0 0;}
div.Allocate{background-image:url(../images/command.png);background-repeat:no-repeat;background-position:-22px 0;}
div.Truncate{background-image:url(../images/command.png);background-repeat:no-repeat;background-position:-44px 0;}
div.TextCalc{background-image:url(../images/TextCalculate.png),url(../images/Line.png);background-repeat:no-repeat,repeat-x;background-position:0 0;}
div.TextAllocate{background-image:url(../images/TextSave.png),url(../images/Line.png);background-repeat:no-repeat,repeat-x;background-position:0 0;}
div.TextTruncate{background-image:url(../images/TextRemove.png),url(../images/Line.png);background-repeat:no-repeat,repeat-x;background-position:0 0;}
div.EditOverGreen, div.TextEditOverGreen, div.AllocateOverGreen, div.TextAllocateOverGreen, div.TextCalcOverGreen, div.CalcOverGreen, div.TruncateOverGreen, div.TextTruncateOverGreen{background-position-y:-22px;}
